// the CRC32 checksum of its associated data file along with the algorithm used
// to compute it, enabling integrity checking of snapshot data on disk.
package sidecar

import (
	"encoding/json"
	"fmt"
	"os"

	"github.com/rqlite/rqlite/v10/internal/rsum"
)

// TypeCastagnoli identifies the Castagnoli polynomial variant of CRC32.
const TypeCastagnoli = "castagnoli"

// Sidecar represents a CRC sidecar record for a snapshot data file.
type Sidecar struct {
	// CRC is the lowercase hex-encoded checksum value.
	CRC string `json:"crc"`

	// Type is the algorithm type identifier (e.g. TypeCastagnoli).
	Type string `json:"type"`

	// Disabled indicates whether integrity checking is disabled.
	Disabled bool `json:"disabled,omitempty"`
}

// NewCastagnoli returns a Sidecar for the given Castagnoli CRC32 value. The CRC
// field is set to the lowercase 8-character hex representation of crc, Type is
// set to TypeCastagnoli, and Disabled is set to false.
func NewCastagnoli(crc uint32) *Sidecar {
	return &Sidecar{
		CRC:  fmt.Sprintf("%08x", crc),
		Type: TypeCastagnoli,
	}
}

// CRC32 parses the CRC field and returns the checksum as a uint32. It returns
// an error if the Type is not a recognized algorithm, or if the CRC field is
// not exactly 8 lowercase hexadecimal characters.
func (s *Sidecar) CRC32() (uint32, error) {
	if s.Type != TypeCastagnoli {
		return 0, fmt.Errorf("unknown sidecar type %q", s.Type)
	}
	if len(s.CRC) == 0 {
		return 0, fmt.Errorf("empty CRC")
	}
	if len(s.CRC) != 8 {
		return 0, fmt.Errorf("invalid CRC length %d, want 8", len(s.CRC))
	}

	var sum uint32
	for _, c := range s.CRC {
		var v uint32
		switch {
		case c >= '0' && c <= '9':
			v = uint32(c - '0')
		case c >= 'a' && c <= 'f':
			v = uint32(c-'a') + 10
		default:
			return 0, fmt.Errorf("invalid CRC character %q", c)
		}
		sum = sum<<4 | v
	}
	return sum, nil
}

// WriteFile writes a sidecar file to path as a JSON object with a "crc" field
// (the lowercase 8-character hex representation of sum) and a "type" field set
// to "castagnoli". It returns a non-nil error on any I/O failure.
func WriteFile(path string, sum uint32) error {
	b, err := json.Marshal(NewCastagnoli(sum))
	if err != nil {
		return err
	}
	return os.WriteFile(path, b, 0644)
}

// ReadFile reads and JSON-unmarshals the sidecar file at path into a Sidecar.
// It returns a non-nil error if the file does not exist or if its contents are
// not valid JSON.
func ReadFile(path string) (*Sidecar, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	s := &Sidecar{}
	if err := json.Unmarshal(b, s); err != nil {
		return nil, fmt.Errorf("invalid sidecar file %s: %w", path, err)
	}
	return s, nil
}

// ReadCRC32File reads the sidecar file at path and returns the stored CRC32 as
// a uint32. It returns a non-nil error if the file cannot be read or if the
// Type field is not a recognized algorithm type.
func ReadCRC32File(path string) (uint32, error) {
	s, err := ReadFile(path)
	if err != nil {
		return 0, err
	}
	return s.CRC32()
}

// CompareFile computes the CRC32 of the data file at dataPath, reads the
// sidecar file at sidecarPath, and compares the two checksums. It returns
// (true, nil) when they match, (false, nil) when they do not match, and a
// non-nil error when either file cannot be read or parsed.
func CompareFile(dataPath, sidecarPath string) (bool, error) {
	expected, err := ReadCRC32File(sidecarPath)
	if err != nil {
		return false, fmt.Errorf("reading sidecar file: %w", err)
	}
	actual, err := rsum.CRC32(dataPath)
	if err != nil {
		return false, fmt.Errorf("calculating CRC32 of data file: %w", err)
	}
	return expected == actual, nil
}
